head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// getWindow(info) 반환 객체가 "Tab 페이지의 Scope" 인지 "브라우저 window" 인지 판별하고,
//  개발자가 실제로 하려는 일(Tab 페이지 컴포넌트 제어)이 되는지까지 확인한다.
scwin.inspect = function (info) {
    var objTab = $p.getComponentById("target1");
    var strCall = "getWindow(" + (typeof info === "string" ? "'" + info + "'" : info) + ")";
    var objRow = { call : strCall, kind : "", ctrl : "", label : "", err : "" };

    var objWin = null;
    try {
        objWin = objTab.getWindow(info);
    } catch (objError) {
        objRow.kind = "호출 실패";
        objRow.err = String(objError);
        return objRow;
    }

    objRow.kind = Object.prototype.toString.call(objWin);

    // 실제 사용 시나리오 : Tab 페이지의 button(link_1) 을 제어한다
    try {
        objRow.label = objWin.link_1.getLabel();
        objRow.ctrl = "가능";
    } catch (objError) {
        objRow.ctrl = "불가";
        objRow.err = String(objError);
    }
    return objRow;
};



// 세 Tab 을 한 번에 호출해 나란히 비교한다
scwin.btn_compareAll_onclick = function (e) {
    var arrCase = [
        { info : 0, desc : "index 0 / tabs1 / wframePreload" },
        { info : 1, desc : "index 1 / tabs2 / pageFrame" },
        { info : 2, desc : "index 2 / tabs3 / wframePreload" }
    ];

    scwin.setReturnValue("=====Tab 페이지 컴포넌트 제어 가능 여부=====");
    var nFail = 0;
    for (var i = 0; i < arrCase.length; i++) {
        var objRow = scwin.inspect(arrCase[i].info);
        scwin.setReturnValue("· " + arrCase[i].desc);
        scwin.setReturnValue("    반환 객체 : " + objRow.kind);
        if (objRow.ctrl === "가능") {
            scwin.setReturnValue("    getWindow(...).link_1.getLabel() -> '" + objRow.label + "'  (제어 가능)");
        } else {
            nFail++;
            scwin.setReturnValue("    getWindow(...).link_1.getLabel() -> 실패  (제어 불가)");
            scwin.setReturnValue("    오류 : " + objRow.err);
        }
    }

    scwin.setReturnValue("");
    scwin.setReturnValue("----- 판정 -----");
    if (nFail === 0) {
        scwin.setReturnValue("세 Tab 모두 Tab 페이지의 컴포넌트를 제어할 수 있다 (frameMode 에 관계없이 동일)");
    } else {
        scwin.setReturnValue("제어 불가 " + nFail + "건 — frameMode 에 따라 getWindow() 반환 형태가 달라진다");
    }
    scwin.setReturnValue("");
};



// 단건 출력(기존 방식 유지)
scwin.printWindow = function (info) {
    var objRow = scwin.inspect(info);
    scwin.setReturnValue(objRow.call + " 반환 객체 : " + objRow.kind);
    if (objRow.ctrl === "가능") {
        scwin.setReturnValue(objRow.call + " -> link_1.getLabel() : '" + objRow.label + "' (제어 가능)");
    } else {
        scwin.setReturnValue(objRow.call + " -> link_1 제어 불가 : " + objRow.err);
    }
};

// 인덱스로 호출
scwin.btn_getWindowIndex_onclick = function (e) {
    scwin.printWindow(Number($p.getComponentById("par_index").getValue()));
};

// Tabs ID 로 호출
scwin.btn_getWindowId_onclick = function (e) {
    scwin.printWindow($p.getComponentById("par_tabsId").getValue());
};
